  let below = null;
  try { below = statesBelow(model); } catch (_) { below = null; }
  let belowMax = 0;
  if (below) for (const id of below.keys()) if (Number.isFinite(id) && id > belowMax) belowMax = id;
  const theModsGap = (i) => !below || !below.size || i > belowMax || below.has(i);
  const highest = () => { let m = 0; for (const n of have) if (n > m) m = n; return m; };
  const gaps = [];
