  const retaken = (w) => w.landed && byId.has(w.id);
  for (const w of want) if (!retaken(w)) ids.delete(w.id);
  // Auto-fix deletes the empty states before it closes the gaps (fixEmptyStates, deleteState), so the slide is worked out without them
  const swept = [];
