  if (lookModes ? [...lookModes.values()].some((m) => !isLookMode(m)) : (look !== null && !isLookMode(look))) return { changed: false, pixels: 0, error: `unknown look "${lookModes ? [...lookModes.values()].find((m) => !isLookMode(m)) : look}"` };
