  const stamp = (f) => { try { const s = fs.statSync(f); return [path.resolve(f), s.size, s.mtimeMs, novaWritesTo(f)].join("|"); } catch (_) { return f; } };
  const key = stamp(pPath) + "#" + stamp(tPath) + "#" + [...spawn].sort((a, b) => a - b).join(",");
  if (_cityGroundByColourCache.has(key)) return _cityGroundByColourCache.get(key);
