    const r = editStateBlock({ modRoot, gameRoot, dependencyRoots, stateId: sid }, (b) => { const t = takeProvinceHistory(removeProvinceFromBlock(b, pid), pid); pieces = t.pieces; const sl = cutStrategicLocationsOfProvince(t.block, pid); strategicLocations = sl.locations; return sl.block; });
