      if (!(row && row.from > 0 && row.to > 0) || width(row.from, row.to) > 0 || !isLand(row.from) || !isLand(row.to)) continue;
      let water = false;
      if (row.through > 0 && byId.has(row.through)) water = isWater(row.through);
      else { const between = provincesBetween(ex, row.from, row.to); water = !!between && between.size > 0 && [...between].every(isWater); }
      if (water) { strait.add(pairOf(row.from, row.to)); wet.add(pairOf(row.from, row.to)); } else dry.push(row);
