        if (!strays.has(sid)) strays.set(sid, []);
        strays.get(sid).push({ type, key: `${sid};${type.toLowerCase()};${String(c[2]).trim()};${String(c[4]).trim()}`, province: v.province, where: v.where });
        strayKeys.add(strays.get(sid)[strays.get(sid).length - 1].key);
