    let to = null, why = "", lost = false;
    if (was != null && now != null && now !== was && Math.abs(rot - was) <= 0.005) { to = now; why = "nova"; }
    else if (o.armLeftTheSea && coastRowArmOnSea(exB, typeBefore, x, z, rot) && !coastRowArmOnSea(ex, typeAfter, x, z, rot)) { to = now; why = "arm"; }
    // ⛔ #a-harbour-keeps-facing-its-sea — AN EDIT TURNS A ROW ONTO THE SEA, NOT TOWARD IT: where coastFacing's answer leaves the water
    // side on land (sea on both flanks of the stroke, the centroid between them), the rotation that puts it on the sea (coastArmFacing);
    // where none does, the stroke left the row too little sea to face, and it goes to its province's new shore as one left none would
    // (review E-R10). A Nova row whose side never was on the sea keeps tracking coastFacing, as Redraw regions' call (no `opts`) does
    if (why && o.armLeftTheSea && (to == null || !coastRowArmOnSea(ex, typeAfter, x, z, to))) {
      const best = coastArmFacing(ex, typeAfter, x, z, to == null ? rot : to);
      if (best != null) to = best;
      else if (why === "arm" || coastRowArmOnSea(exB, typeBefore, x, z, rot)) { to = null; lost = true; }
    }
    if (to != null && o.armLeftTheSea && Math.abs(to - rot) <= 0.005) continue;   // the row's own rotation is that answer: left, and not said
    if (to != null) {
      c[5] = to.toFixed(2);
      parts[i] = c.join(";");
      turned.push({ type, x, z, from: rot, to, why, province: owner });
      if (isLead && owner != null) lead.set(owner, { x, y: c[3], z, rot: to, x0: x, z0: z, rot0: rot, changed: true });
      continue;
    }
    // …AND ONE THE EDIT TOOK EVERY SEA IN REACH FROM GOES TO ITS PROVINCE'S COAST. The base game stands every port, dockyard, fort,
    // hub and HQ on land with a sea in coastFacing's reach (99.6–100%, e-design-vanilla-shape.js); that stroke left 5 of the 22 rows
    // beside it with none, each on a province still on the sea within 8 px of it. So does one it left too little sea to face (`lost`),
    // and there it is turned as a turned row is: onto the sea where coastFacing's answer is not (2 of 33 moved rows were, E-R10's sweep)
    if (!o.armLeftTheSea || typeof o.coastPixel !== "function" || (!lost && (coastSeaInReach(ex, typeAfter, x, z) || !coastSeaInReach(exB, typeBefore, x, z)))) continue;
    const at = o.coastPixel(c, x, z, owner);
    if (!at || !(at.x >= 0)) {
      stranded.push({ type, x, z, province: owner, why: (at && at.why) || "no coast" });
      if (isLead && owner != null) lead.get(owner).why = (at && at.why) || "no coast";   // its ship is said with it (below)
      continue;
    }
    const nz = pixelYToBuildingZ(ex.H, at.row);
    let nrot = coastFacing(ex, typeAfter, at.x, nz);
