    const x = Math.floor(A.x + (dx * i) / n + 0.5), row = Math.floor(A.row + (dy * i) / n + 0.5);
    if (x < 0 || x >= W || row < 0 || row >= H) { hs.push(-1); last = -1; continue; }
    const at = row * W + x;
    if (at === last) continue;
    last = at;
    hs.push(isLandAt(x, row) ? heightAt(x, row) : -1);
