  const { H } = ex, tx = (P) => Math.trunc(P.x + 1e-7), trow = (P) => H - 1 - Math.trunc(H - 1 - P.row + 1e-7);
  const ax = tx(A), ar = trow(A), bxx = tx(B), br = trow(B);
