    const t = i / RAIL_TRACK_STEPS, u = 1 - t, k0 = u * u * u, k1 = 3 * u * u * t, k2 = 3 * u * t * t, k3 = t * t * t;
    out.push({ x: k0 * X1.x + k1 * C1.x + k2 * C2.x + k3 * X2.x, row: k0 * X1.row + k1 * C1.row + k2 * C2.row + k3 * X2.row });
