        const w = classes.weightOf(t, (extents.sumY.get(id) / k + 0.5) / H);
        weight.set(id, w.px); groundOf.set(id, { terrain: t, px: w.px }); from[w.from]++; provisional[t] = (provisional[t] || 0) + 1;
