  const have = new Set((palette || []).map((s) => String(s).toLowerCase()));
  const usable = Object.keys(TERRAIN_HOPS_FROM_SEA).filter((t) => have.has(t));
  if (!usable.length) return out;   // this mod's terrain table names none of them — the caller's default stands
  // #a-generated-terrain-follows-the-latitude-below — the lift, when the latitude below is known; then id order, for every draw below
