        // province of this ground becomes, so the pieces come out in the mix the click deals the land by
        let ws = f == null ? weights : weights.map((x) => ({ t: x.t, w: x.w * lift(f, x.t) * (sizeOf ? sizeOf(id, x.t, f) : 1) }));
        let sum = 0;
