  const amount = (o, kind, k) => num(k == null ? (o || {})[kind] : ((o || {})[kind] || {})[k]);
  const of = (m, t) => (m instanceof Map ? m.get(t) : null);
  const receivers = [...(standsOn instanceof Map ? standsOn : [])].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  const quantities = [["manpower", null]], seen = new Set();
  for (const [, by] of receivers) for (const w of by.values()) for (const kind of ["buildings", "resources"]) {
    for (const k of Object.keys((w && w[kind]) || {}).sort()) if (!seen.has(`${kind} ${k}`)) { seen.add(`${kind} ${k}`); quantities.push([kind, k]); }
  }
