  const modB = path.join(modRoot, "map", "buildings.txt");
  let bSrc = fs.existsSync(modB) ? modB : "";
  // #a-replaced-map-folder-is-judged-by-its-own-files — the buildings.txt that LOADS (layersBelow, B6-17): under the mod's own replace_path="map"
