  let bmpSrc = fs.existsSync(bp) ? bp : "";
  if (!bmpSrc) for (const r of layersBelow(modRoot, gameRoot, dependencyRoots, "map")) { const p = path.join(r, "map", "provinces.bmp"); if (fs.existsSync(p)) { bmpSrc = p; break; } }
