    let four = false; for (let k = 1; k < 8; k += 2) { const q = nb(j, RASTER_RING_DX[k], RASTER_RING_DY[k]); if (q >= 0 && id[q] === back) four = true; }
    if (!four || area.get(own) - 1 < floor.get(own) || !seamOk(j, back) || !rasterIsSimplePoint(W, H, id, j, own)) return false;
