    const look = new Set();
    for (let i = 0; i < N; i++) if (id[i] !== id0[i]) for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) { const q = nb(i, dx, dy); if (q >= 0) look.add(q); }
    const bad = [...look].filter(isBad);
