    if (!airWingKeyMoves({ tag: T, ownerNow: O, ownerBeneath: was, noted })) continue;   // the world beneath based it there already
    out.wings.push(Object.assign({}, u, { owner: O, was, origin, noted, nth, oldProvinces: ((below && below.provinces) || []).map(Number), ...(date ? { date } : {}) }));
