    let d = 0, close = -1;
    for (let i = open; i < s.length; i++) { if (s[i] === "{") d++; else if (s[i] === "}") { d--; if (d === 0) { close = i; break; } } }
    if (close === -1) break;                              // unterminated — leave the rest alone
    if (depth === 0) { out.push({ key: m[1], body: s.slice(open + 1, close) }); re.lastIndex = close + 1; }
    else re.lastIndex = m.index + m[0].length;
