  if (sl.effect !== "strategic_province_location" || sl.dated || !Number.isFinite(sl.province)) return null;
  if (!(owned || new Set(st.provinces || [])).has(sl.province)) return null;
  const bundle = strategicLocationBundles(model).get(sl.location);
  if (!bundle) return null;
  const prov = provinceIndexFor(model).get(sl.province);
  if (!prov || prov.coastal) return null;
  const coastOnly = coastOnlyBuildings(model);
  const buildings = Object.keys(bundle).filter((b) => coastOnly.get(b) === true);
  if (!buildings.length) return null;
