    try { mine = nameIn(fs.readFileSync(path.join(modRoot, "descriptor.mod"), "utf8")); } catch (_) { return null; }
    if (!mine.name) return null;
    const store = path.dirname(own);
    let names = [];
    try { names = fs.readdirSync(store, { withFileTypes: true }).filter((e) => e.isDirectory() && /_[0-9a-f]{10}$/.test(e.name)).map((e) => e.name); } catch (_) { return null; }
