    for (const n of names) {
      const d = path.join(store, n);
      if (samePath(d, own)) continue;
      try {
        const m = JSON.parse(fs.readFileSync(path.join(d, "_baseline.json"), "utf8"));
        if (!m || !m.modRoot || samePath(m.modRoot, modRoot)) continue;
        const ownDesc = (Array.isArray(m.descriptors) ? m.descriptors : []).find((x) => x && x.kind === "mod" && typeof x.copy === "string");
        if (!ownDesc) continue;
        const theirs = nameIn(fs.readFileSync(path.join(d, ...ownDesc.copy.split("/")), "utf8"));
        if (theirs.name !== mine.name || (theirs.remote && mine.remote && theirs.remote !== mine.remote)) continue;
        // …and the mod is no longer where it was saved: the folder's own descriptor.mod, as it is now, names another mod or is gone
        let there = null;
        try { there = nameIn(fs.readFileSync(path.join(m.modRoot, "descriptor.mod"), "utf8")); } catch (_) { there = null; }
        if (there && there.name === mine.name && !(there.remote && mine.remote && there.remote !== mine.remote)) continue;
        if (!best || String(m.savedAt || "") > String(best.savedAt || "")) best = { dir: d, savedFor: path.resolve(m.modRoot), savedAt: m.savedAt };
      } catch (_) { /* not a whole baseline: never offered */ }
    }
