      empty: dirs ? dirs.length === 0 : undefined, sizeMB: Math.round(_dirSizeBytes(dir) / 1048576),
      asked, heldUnits: !!(asked && asked.some((a) => baselineRel(a) === "history/units")), heldDescriptors: Array.isArray(meta.descriptors),
      // …and the minimap, the colour-grading boxes and Nova's region names (#a-restored-map-keeps-its-pictures-and-names, R4)
      heldFiles: Array.isArray(meta.files), ...(heldVerdict ? { heldVerdict } : {}),
